entries[23643] = { ["name"] = "Purifying Earth", ["text"] = "Quest Item\n\"This clump of earth, found at the core of a boulderkin, radiates a sense of purity absent from the rest of the elemental's body.\"" }
entries[23644] = { ["name"] = "Crate of Reagents", ["text"] = "Binds when picked up\nUnique\n\"A container full of the reagents needed to make a trial dose of Magistrix Elosai's tonic.\"" }
