entries[23655] = { ["name"] = "Elven Manacles", ["text"] = "Quest Item\nUse: Apply manacles to a wounded Bloodscalp Shaman to subdue and capture it.\n\"A wicked-looking restraint device of exquisite craftsmanship.\"" }
entries[23657] = { ["name"] = "Dawn Runner Cargo", ["text"] = "Quest Item\nUnique\n\"The remaining cargo from the holds of the Dawn Runner.\"" }
